import {readdirSync,readFileSync,writeFileSync} from "node:fs";
import {join,resolve,extname} from "node:path";
import {fileURLToPath} from "node:url";
const root=resolve(fileURLToPath(new URL("../dist/",import.meta.url)));
const prefix="/drlucascarazza";
let changed=0;
function visit(dir){
  for(const entry of readdirSync(dir,{withFileTypes:true})){
    const full=join(dir,entry.name);
    if(entry.isDirectory()) {visit(full);continue;}
    if(![".html",".css",".js"].includes(extname(full)))continue;
    let raw=readFileSync(full,"utf8");
    const prev=raw;
    // Handles HTML generated by Astro, static legacy markup and absolute media references.
    raw=raw.replace(/\b(href|src|poster|action|content)=(["'])\/(?!\/|drlucascarazza\/)/g,(_,attr,q)=>attr+"="+q+prefix+"/");
    raw=raw.replace(/\b(srcset)=(["'])([^"']*)\2/g,(_full,attr,q,value)=>attr+"="+q+value.replace(/(^|,\s*)\//g,"$1"+prefix+"/")+q);
    raw=raw.replace(/url\((["']?)\/(?!\/|drlucascarazza\/)/g,(_full,q)=>"url("+q+prefix+"/");
    if(raw!==prev){writeFileSync(full,raw);changed++;}
  }
}
visit(root);
console.log("GitHub Pages:",changed,"arquivos adaptados ao prefixo",prefix);
